"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[9044],{62119:e=>{e.exports=JSON.parse('{"functions":[{"name":"Fetch","desc":"Creates the `Sound` with that name. If the name is not in the schema, a warning is printed and a silent blank\\n`Sound` named `VluxySF_Blank_Sound` is returned instead, so calling code never has to nil-check.\\n\\n:::info\\n- A warmed sound (see `Cache`) is cloned from its template.\\n- A sound fetched without a parent is placed in `SoundService.UnattachedSounds`. So is one whose parent refused\\nit (a locked or destroyed Instance), with a warning. A parent that is not an Instance, or a preset that is not a\\nfunction, is warned about and ignored.\\n- Called before the library has started, it warns once and returns a blank `Sound` instead of erroring, so early\\ngame code keeps running. The blank is parented to `parent` when one was given and stays unparented otherwise;\\nthe preset is not applied to it.\\n- An error thrown by the preset is yours and propagates; the sound it was applied to is destroyed first.\\n:::\\n\\n```lua\\nlocal mySound = VluxySF.Fetch(\\"MySound\\")\\nmySound.Volume = 0.3\\n\\nlocal echo = mySound:FindFirstChild(\\"EchoSoundEffect\\")\\nif echo then\\n\\techo.WetLevel = 1.3\\nend\\n\\nmySound:Play()\\n```","params":[{"name":"name","desc":"The name of the `Sound`.","lua_type":"string"},{"name":"parent","desc":"Parent of the `Sound`.","lua_type":"Instance?"},{"name":"preset","desc":"`Preset` to apply before parenting.","lua_type":"((Sound) -> ())?"}],"returns":[{"desc":"The new `Sound`.","lua_type":"Sound"}],"function_type":"static","tags":["RequiresSchema"],"source":{"line":162,"path":"lib/Api/Fetch.luau"}},{"name":"TryFetch","desc":"The same as `Fetch`, but returns `nil` instead of a blank sound when the name is not in the schema, or when the\\nlibrary has not started yet. Use it for names built at runtime or sounds that may not exist.\\n\\n```lua\\nlocal voiceLine = VluxySF.TryFetch(`VO_{npcName}`, head)\\n\\nif voiceLine then\\n\\tvoiceLine:Play()\\nend\\n```","params":[{"name":"name","desc":"The name of the `Sound`.","lua_type":"string"},{"name":"parent","desc":"Parent of the `Sound`.","lua_type":"Instance?"},{"name":"preset","desc":"`Preset` to apply before parenting.","lua_type":"((Sound) -> ())?"}],"returns":[{"desc":"The new `Sound`, or `nil`.","lua_type":"Sound?"}],"function_type":"static","tags":["RequiresSchema"],"source":{"line":209,"path":"lib/Api/Fetch.luau"}},{"name":"OneShot","desc":"Plays a sound once and cleans it up: builds it, turns looping off, plays it and destroys it when it ends. Returns a\\nfunction that stops and destroys it early.\\n\\nNothing has to wait for the audio to load: Roblox holds a played sound until its audio arrives and starts it from\\nthe beginning. If the audio has not loaded within 10 seconds (deleted, moderated or private audio never does), a\\nwarning is printed and the sound is destroyed. With a name that is not in the schema, or before the library has\\nstarted, a warning is printed and nothing plays. Destroying the parent while the sound plays is fine: the sound\\ngoes with it and nothing is reported.\\n\\n```lua\\nVluxySF.OneShot(\\"Hit\\", character.HumanoidRootPart)\\n\\nlocal stop = VluxySF.OneShot(\\"Charge\\")\\n-- later, if it has to end early:\\nstop()\\n```\\n\\n:::info\\n`Sound.Played` fires and `IsPlaying` turns true as soon as the sound is played, before its audio has loaded. Code\\nthat needs the sound to be audible should wait for `Sound.Loaded`.\\n:::","params":[{"name":"name","desc":"The name of the `Sound`.","lua_type":"string"},{"name":"parent","desc":"Parent of the `Sound`.","lua_type":"Instance?"},{"name":"preset","desc":"`Preset` to apply before parenting.","lua_type":"((Sound) -> ())?"}],"returns":[{"desc":"Stops and destroys the `Sound` early.","lua_type":"() -> ()"}],"function_type":"static","tags":["RequiresSchema"],"source":{"line":259,"path":"lib/Api/Fetch.luau"}},{"name":"WithWrapper","desc":"Returns a copy of the library whose `Fetch` and `TryFetch` pass every fetched `Sound` through `wrap` and return\\nwhat it returns. Use it to get your own sound class, with methods like fades, out of every fetch.\\n\\nThe copy is fully typed: whatever type `wrap` returns is what `Fetch` returns. `VluxySF` itself is not changed, so\\nother scripts and packages that require it still get plain `Sound`s.\\n\\n:::tip\\nCall this once in a module of your own and require that module everywhere. The Wrapping Sounds guide shows the\\nsetup.\\n:::\\n\\n```lua\\nlocal Sounds = VluxySF.WithWrapper(function(sound)\\n\\treturn MySoundClass.new(sound)\\nend)\\n\\nSounds.Fetch(\\"MySound\\"):FadeIn(1)\\n```\\n\\n:::info\\n- Presets still receive the `Sound` before it is wrapped.\\n- `Fetch` wraps the blank sound it returns for an unknown name. `TryFetch` returns `nil` without calling `wrap`.\\n- `OneShot` is unchanged, since a one-shot cleans itself up.\\n- If `wrap` errors, the fetched `Sound` is destroyed and the error is passed on, since it comes from your code.\\n:::","params":[{"name":"wrap","desc":"Turns a fetched `Sound` into your wrapper.","lua_type":"(Sound) -> T"}],"returns":[{"desc":"The library with wrapping fetch functions.","lua_type":"Wrapped<T>"}],"function_type":"static","source":{"line":91,"path":"lib/Api/Wrapping.luau"}}],"properties":[],"types":[{"name":"Wrapped<T>","desc":"The library returned by `WithWrapper`. The same as `VluxySF`, except that `Fetch` and `TryFetch` return the\\nwrapper instead of the `Sound`.","lua_type":"VluxySF","source":{"line":25,"path":"lib/Api/Wrapping.luau"}}],"name":"VluxySF","desc":"Vluxy Sound Factory. Build your sounds in Studio once, then fetch any of them by name from the server or the\\nclient.\\n\\n```lua\\nlocal sound = VluxySF.Fetch(\\"MySound\\")\\nsound:Play()\\n```","realm":["Client","Server"],"source":{"line":66,"path":"lib/init.luau"}}')}}]);